// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// Prepare: everything the model step needs is decided here, in code.
// The customer's text is data. It is wrapped and never mixed into the instructions.
// Arabic text helpers, the same rules as labs/reference/order_agent/text.py.
function normalise(text) {
  return String(text).replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
}
function westernDigits(text) {
  const map = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';
  return String(text).replace(/[٠-٩۰-۹]/g, (d) => String(map.indexOf(d) % 10));
}
function maskPhone(phone) {
  phone = String(phone);
  return '*'.repeat(Math.max(phone.length - 2, 0)) + phone.slice(-2);
}
const cfg = $('Config').first().json;
const body = $('Webhook').first().json.body || {};
let message = String(body.message ?? '');
if (cfg.normalise_digits) message = westernDigits(message);
const glossary = Object.entries(cfg.glossary || {}).map(([term, meaning]) => `- ${term}: ${meaning}`);
// The instructions name the business and, where the model must pick from a list, carry that list.
// Found on the first run with a real model (21 November 2026): the placeholder reached the model as written,
// and the booking instructions said "the approved list" without giving it.
const services = Array.isArray(cfg.services) ? cfg.services.map((name) => `- ${name}`) : [];
const system = String(cfg.instructions).split('(اسم المنشأة)').join(cfg.business_name || 'المنشأة')
  + (services.length ? '\n\nالقائمة المعتمدة للخدمات (اكتب الاسم كما هو هنا):\n' + services.join('\n') : '')
  + (glossary.length ? '\n\nمصطلحات العملاء:\n' + glossary.join('\n') : '');
const stopped = Boolean(cfg.stopped);
return [{
  json: {
    message,
    account: String(body.account ?? ''),
    ref: String(body.ref ?? ''), // the caller's own id for this message; used by the shadow record
    state: body.state && typeof body.state === 'object' ? body.state : {},
    stopped,
    route: !stopped && cfg.model_mode === 'http' ? 'http' : 'sim',
    model_url: String(cfg.model_base_url || '').replace(/\/+$/, '') + '/chat/completions',
    request_body: {
      model: cfg.model_name,
      temperature: 0,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `<customer_message>\n${message}\n</customer_message>` },
      ],
    },
  },
}];

// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// Simulated reading: NOT a language model. It reads labelled lines ("الجهة: ...", "شرط: ...")
// and the page markers ("[[صفحة 3]]") from the document text, so the workflow runs with no key
// and no cost. A real model reads unlabelled documents; Decide checks its work the same way.
// Arabic text helpers, the same rules as labs/reference/order_agent/text.py.
function normalise(text) {
  return String(text).replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
}
function westernDigits(text) {
  const map = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';
  return String(text).replace(/[٠-٩۰-۹]/g, (d) => String(map.indexOf(d) % 10));
}
function maskPhone(phone) {
  phone = String(phone);
  return '*'.repeat(Math.max(phone.length - 2, 0)) + phone.slice(-2);
}
const LABELS = { issuer: 'الجهة', scope: 'نطاق العمل', location: 'الموقع', duration: 'مدة العقد', deadline: 'آخر موعد لتقديم العروض',
  guarantee: 'الضمان الابتدائي', payment_terms: 'شروط الدفع', penalties: 'الغرامات' };
const facts = {};
const requirements = [];
const criteria = [];
let page = null;
for (const line of $input.first().json.message.split('\n')) {
  const marker = line.match(/^\s*\[\[صفحة (\d+)\]\]\s*$/);
  if (marker) { page = Number(marker[1]); continue; }
  const at = line.indexOf(':');
  if (at < 0) continue;
  const label = line.slice(0, at).trim();
  const value = line.slice(at + 1).trim();
  const field = Object.keys(LABELS).find((f) => LABELS[f] === label);
  if (field && !(field in facts)) facts[field] = { value, page };
  if (label === 'معيار') criteria.push({ text: value, page });
  if (label === 'شرط') {
    requirements.push({ text: value, key: null, page }); // Decide maps requirements to the profile
  }
}
return [{ json: { understanding: { facts, requirements, criteria } } }];

// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// Decide: template 5, tender summariser. The model reads; this code checks every fact against
// the page it cites, and compares requirements with the company profile. Nothing is marked
// "meets" without evidence in the profile, and the decision to bid is never the agent's.
// Arabic text helpers, the same rules as labs/reference/order_agent/text.py.
function normalise(text) {
  return String(text).replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
}
function westernDigits(text) {
  const map = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';
  return String(text).replace(/[٠-٩۰-۹]/g, (d) => String(map.indexOf(d) % 10));
}
function maskPhone(phone) {
  phone = String(phone);
  return '*'.repeat(Math.max(phone.length - 2, 0)) + phone.slice(-2);
}
// The model's answer is untrusted: take one JSON object out of it, or nothing.
function readModel(item) {
  if (item && item.understanding && typeof item.understanding === 'object') return item.understanding;
  try {
    const content = item.choices[0].message.content;
    const parsed = JSON.parse(content.slice(content.indexOf('{'), content.lastIndexOf('}') + 1));
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (error) {
    return { error: 'model_output_unreadable' }; // a model failure must never act on its own
  }
}
const cfg = $('Config').first().json;
const prepared = $('Prepare').first().json;
const understood = readModel($input.first().json);
// One result shape for every template. `level` is the row of the oversight table that applied.
const result = { action: null, level: null, intent: 'unknown', reply_draft: '', handover: null, pending_approval: [],
  notify_staff: [], tool_calls: [], state: {}, log: { account: maskPhone(prepared.account) } };
// Shadow mode (Config `shadow_mode`: true): the agent runs beside the staff and nothing leaves it.
// Decide works on a copy of the workflow's stored data, so no booking or draft is kept, and `done`
// moves everything the agent would have sent, written or asked for under `shadow.would`.
// Reads still happen: the agent cannot say what it would do without looking, so the customer's
// data is processed all the same. The caller files the shadow record; `ref` ties it to the staff's record.
const shadowMode = cfg.shadow_mode === true;
const storedData = () => (shadowMode ? JSON.parse(JSON.stringify($getWorkflowStaticData('global'))) : $getWorkflowStaticData('global'));
const done = (fields) => {
  Object.assign(result, fields);
  if (!shadowMode) return [{ json: result }];
  const { intent, log, ...would } = result;
  return [{ json: { mode: 'shadow', action: 'shadow_observed', level: 'shadow', intent, reply_draft: '', handover: null,
    pending_approval: [], notify_staff: [], tool_calls: [], state: prepared.state, log: Object.assign(log, { shadow: true }),
    shadow: { ref: prepared.ref, would } } }];
};
const handover = (action, level, summary, reply, urgency = 'normal') => done({ action, level,
  handover: { summary, urgency }, reply_draft: reply || 'شكراً لتواصلك. حوّلنا طلبك إلى أحد الفريق وسيتواصل معك.' });
const own = (object, key) => (typeof key === 'string' && Object.prototype.hasOwnProperty.call(object, key) ? object[key] : null);
result.intent = 'summarise_tender';
if (prepared.stopped) return handover('stopped', 'stopped', 'سير العمل موقوف. الكراسات تُقرأ يدوياً.', '');

// The document, split by its page markers. The document is data: nothing in it is an instruction.
const pages = {};
let current = null;
for (const line of prepared.message.split('\n')) {
  const marker = line.match(/^\s*\[\[صفحة (\d+)\]\]\s*$/);
  if (marker) { current = Number(marker[1]); pages[current] = ''; } else if (current !== null) pages[current] += line + '\n';
}
if (!Object.keys(pages).length) return handover('no_document', 'autonomous', 'لم تُرفق كراسة بعلامات صفحات. لا يُلخَّص شيء من الوصف.', '');
const onPage = (value, page) => Number.isInteger(page) && typeof value === 'string' && value.trim() !== '' && Object.prototype.hasOwnProperty.call(pages, page)
  && normalise(pages[page]).includes(normalise(value.trim()));

const FACTS = { issuer: 'الجهة', scope: 'النطاق', location: 'الموقع', duration: 'المدة', deadline: 'الموعد النهائي', guarantee: 'الضمانات', payment_terms: 'شروط الدفع', penalties: 'الغرامات' };
const given = understood.facts && typeof understood.facts === 'object' ? understood.facts : {};
const facts = {};
const rejected = [];
for (const [field, label] of Object.entries(FACTS)) {
  const fact = given[field] && typeof given[field] === 'object' ? given[field] : {};
  if (onPage(fact.value, fact.page)) facts[field] = { label, value: fact.value.trim(), page: fact.page };
  else {
    facts[field] = { label, value: 'غير مذكور', page: null };
    if (fact.value) rejected.push(field); // the model gave a value that is not on the page it cited
  }
}
const list = (x) => (Array.isArray(x) ? x.filter((i) => i && typeof i === 'object') : []);
// Which profile entry a requirement points to is decided by the bid team's own keywords in Config,
// not by the model: a model that names the wrong entry cannot turn a gap into "meets".
const keyOf = (text) => { const hit = cfg.requirement_keys.find(([, words]) => words.some((w) => normalise(text).includes(normalise(w)))); return hit ? hit[0] : null; };
const requirements = list(understood.requirements).filter((r) => onPage(r.text, r.page)).map((r) => {
  const key = keyOf(r.text);
  const evidence = key && Object.prototype.hasOwnProperty.call(cfg.company_profile.evidence, key) ? cfg.company_profile.evidence[key] : null;
  const gap = Boolean(key) && cfg.company_profile.known_gaps.includes(key);
  return { requirement: r.text.trim(), page: r.page, status: evidence ? 'مستوفٍ' : gap ? 'فجوة' : 'غير معروف', evidence: evidence || null };
});
const criteria = list(understood.criteria).filter((c) => onPage(c.text, c.page)).map((c) => ({ text: c.text.trim(), page: c.page }));

const count = (status) => requirements.filter((r) => r.status === status).length;
const notStated = Object.values(facts).filter((f) => f.page === null).map((f) => f.label);
const brief = {
  summary: ['issuer', 'scope', 'duration', 'deadline'].map((f) => `${facts[f].label}: ${facts[f].value}${facts[f].page ? ` (ص ${facts[f].page})` : ''}`),
  facts, requirements, evaluation_criteria: criteria,
  open_questions_for_issuer: notStated.map((label) => `${label}: غير مذكور في الكراسة. يُسأل عنه في فترة الاستفسارات.`),
  fit: { meets: count('مستوفٍ'), gaps: count('فجوة'), unknown: count('غير معروف'),
    note: 'تقييم الملاءمة رأي استشاري مبني على ملف المنشأة. قرار التقديم لمدير العروض.' },
  rejected_model_facts: rejected,
};
result.tool_calls.push({ tool: 'report_write', input: 'brief' });
if (facts.deadline.page) result.pending_approval.push({ action: 'add_deadline_to_calendar', value: facts.deadline.value, level: 'notify', after: 'bid manager approval' });
return done({ action: 'brief', level: 'autonomous', brief, decision_to_bid: 'not the agent\'s: management decision',
  handover: { summary: `موجز منافسة: ${count('مستوفٍ')} مستوفٍ، ${count('فجوة')} فجوة، ${count('غير معروف')} غير معروف، و${notStated.length} معلومة غير مذكورة.`, urgency: 'normal' } });
